from pwn import *
import time

def try_get_flag():
    patterns = ['++++x', '+++x+', '++x++', '+x+++', 'x++++']
    r = remote('misc.chal.csaw.io', 5000, level='error')

    try:
        r.recvuntil(b'check?')
        r.sendline(b'5')
        r.recvuntil(b'bases:')

        # Try each pattern
        for pattern in patterns:
            print(f"\nTrying pattern: {pattern}")
            r.sendline(pattern.encode())

            try:
                while True:
                    line = r.recvline(timeout=2).decode()
                    print(line.strip())
                    if 'flag{' in line.lower():
                        return True, line
                    if 'error' in line.lower():
                        errors = int(line.split(':')[1].strip())
                        if errors == 0:
                            print("Perfect match!")
                        break
            except EOFError:
                break

        r.close()
        return False, None

    except Exception as e:
        print(f"Error: {e}")
        r.close()
        return False, None

def main():
    attempts = 0
    while attempts < 20:
        attempts += 1
        print(f"\nAttempt {attempts}")
        success, flag = try_get_flag()
        if success:
            print(f"Found flag: {flag}")
            break
        time.sleep(1)

if __name__ == "__main__":
    main()

from pwn import *
import time
import re

def try_combination(bases, debug=True):
    try:
        conn = remote('misc.chal.csaw.io', 5000, timeout=5)
        if debug:
            print(f"\nTrying bases: {bases}")

        initial_prompt = conn.recvuntil(b'check?', timeout=5).decode()
        if debug:
            print(f"Initial prompt: {initial_prompt}")

        conn.sendline(str(len(bases)).encode())
        conn.sendline(bases.encode())

        # Try to get full response including potential flag
        response = b""
        try:
            while True:
                chunk = conn.recv(timeout=2)
                if not chunk:
                    break
                response += chunk
        except:
            pass

        response_text = response.decode()
        if debug:
            print(f"Full response: {response_text}")

        # Check for flag format
        if 'flag{' in response_text:
            print("!!! FLAG FOUND !!!")
            print(response_text)
            return 0, response_text

        # Extract error count
        try:
            error_match = re.search(r'(\d+) wrong', response_text)
            if error_match:
                errors = int(error_match.group(1))
                return errors, response_text
        except:
            pass

        conn.close()
        return None, response_text
    except Exception as e:
        print(f"Error: {str(e)}")
        return None, None

def generate_combinations(length, prefix="", patterns=None):
    if patterns is None:
        patterns = []
    if len(prefix) == length:
        patterns.append(prefix)
        return
    for base in ['+', 'x']:
        generate_combinations(length, prefix + base, patterns)
    return patterns

def main():
    base_length = 10
    successful_patterns = []

    # Try some common QKD patterns first
    patterns = [
        '+'*base_length,
        'x'*base_length,
        '+'*(base_length//2) + 'x'*(base_length//2),
        'x'*(base_length//2) + '+'*(base_length//2),
        '+x'*(base_length//2),
        'x+'*(base_length//2)
    ]

    print("[*] Trying initial patterns...")
    for pattern in patterns:
        errors, response = try_combination(pattern)
        if errors == 0:
            successful_patterns.append(pattern)
            print(f"[+] Success with pattern: {pattern}")
            print(f"[+] Response: {response}")
            if 'flag{' in response:
                return
        elif errors is not None:
            print(f"[-] Pattern {pattern} had {errors} errors")
        time.sleep(1)  # Rate limiting

    print("[*] Trying systematic combinations...")
    # If no success, try systematic combinations
    all_patterns = generate_combinations(base_length)
    for pattern in all_patterns:
        errors, response = try_combination(pattern, debug=False)
        if errors == 0:
            successful_patterns.append(pattern)
            print(f"[+] Success with pattern: {pattern}")
            print(f"[+] Response: {response}")
            if 'flag{' in response:
                return
        elif errors is not None:
            print(f"[-] Pattern {pattern} had {errors} errors")
        time.sleep(1)  # Rate limiting

if __name__ == "__main__":
    main()

from pwn import *
import time
import re
from collections import defaultdict

def try_combination(bases, debug=True):
    try:
        conn = remote('misc.chal.csaw.io', 5000, timeout=5)
        if debug:
            print(f"\nTrying bases: {bases}")

        initial = conn.recvuntil(b'check?', timeout=5)
        if not initial:
            conn.close()
            return None, "No initial prompt"

        conn.sendline(str(len(bases)).encode())
        time.sleep(0.5)

        base_prompt = conn.recvuntil(b'bases:', timeout=5)
        if not base_prompt:
            conn.close()
            return None, "No base prompt"

        conn.sendline(bases.encode())

        response = b""
        try:
            while True:
                chunk = conn.recvall(timeout=3)
                if not chunk:
                    break
                response += chunk
        except:
            pass

        response_text = response.decode()
        if debug:
            print(f"Response: {response_text}")

        if 'flag{' in response_text:
            print("\n!!! FLAG FOUND !!!")
            print(response_text)
            conn.close()
            return 0, response_text

        error_match = re.search(r'(\d+) wrong', response_text)
        if error_match:
            errors = int(error_match.group(1))
            if debug:
                print(f"Found {errors} errors")
            conn.close()
            return errors, response_text

        conn.close()
        return None, response_text
    except Exception as e:
        if debug:
            print(f"Error occurred: {str(e)}")
        return None, str(e)

def evolve_pattern(pattern, errors, mutation_rate=0.2):
    new_pattern = list(pattern)
    # Only mutate positions based on error count
    mutations = min(int(errors * mutation_rate) + 1, len(pattern))
    indices = range(len(pattern))
    for i in range(mutations):
        idx = indices[i]
        new_pattern[idx] = '+' if pattern[idx] == 'x' else 'x'
    return ''.join(new_pattern)

def main():
    base_length = 10
    all_patterns = set()
    success_patterns = []

    # Initial patterns
    patterns = [
        'x'*base_length,
        '+'*base_length,
        ('x'+'+')*5,
        ('+'+'x')*5,
        'xxxxx+++++',
        '+++++xxxxx'
    ]

    best_error = float('inf')
    best_pattern = None

    # Learning phase
    patterns_tried = defaultdict(int)

    for iteration in range(100):  # Limit total iterations
        print(f"\n[*] Iteration {iteration}")
        if best_pattern:
            print(f"[*] Best so far: {best_pattern} with {best_error} errors")

        for pattern in patterns:
            if pattern in all_patterns:
                continue

            all_patterns.add(pattern)
            patterns_tried[pattern] += 1

            errors, response = try_combination(pattern)

            if errors is not None:
                if errors < best_error:
                    best_error = errors
                    best_pattern = pattern
                    print(f"[+] New best pattern: {pattern} with {errors} errors")

                if errors == 0:
                    print(f"[!!!] Found perfect match: {pattern}")
                    if 'flag{' in response:
                        return
                    success_patterns.append((pattern, response))

            # Generate new patterns based on error feedback
            if errors is not None and errors > 0:
                new_pattern = evolve_pattern(pattern, errors)
                if new_pattern not in all_patterns:
                    patterns.append(new_pattern)

            time.sleep(1)  # Rate limiting

        # Clear patterns that have been tried too many times
        patterns = [p for p in patterns if patterns_tried[p] < 3]

        # Add some random mutations of the best pattern
        if best_pattern:
            for _ in range(3):
                new_pattern = evolve_pattern(best_pattern, best_error, mutation_rate=0.3)
                if new_pattern not in all_patterns:
                    patterns.append(new_pattern)

    print("\nFinal Results:")
    for pattern, response in success_patterns:
        print(f"Pattern: {pattern}")
        print(f"Response: {response}\n")

if __name__ == "__main__":
    main()
